query searchDeathNoticesForListTableWithoutPhoto($list: ListInput!, $isTiledView: Boolean!) {
  searchDeathNoticesForList(query: $list, isTiledView: $isTiledView) {
    count
    perPage
    page
    nextPage
    records {
      id
      firstname
      surname
      nee
      createdAt
      funeralArrangementsLater
      arrangementsChange
      county { id name }
      town { id name }
    }
  }
}
